<?php
declare(strict_types=1);
$env=[];foreach(file(__DIR__.'/../.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$k,$v]=explode('=',$line,2);$env[trim($k)]=trim(trim($v),'"\'');}
$o=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC];
function dbj(array $e,string $p,string $s,array $o):PDO{return new PDO('mysql:host='.$e[$p.'_DB_HOST'].';port='.$e[$p.'_DB_PORT'].';dbname='.$s.';charset=utf8mb4',$e[$p.'_DB_USERNAME'],$e[$p.'_DB_PASSWORD'],$o);}
$legacy=dbj($env,'LEGADO_SEGURANCA','green_atlas_seguranca',$o);$target=dbj($env,'GPT','gatlas_dbp',$o);
$legacyGroups=$legacy->query("SELECT ug.CODUSUARIO,ug.CODGRUPO,g.DSCGRUPO FROM usuariosxgrupos ug JOIN grupos g ON g.CODGRUPO=ug.CODGRUPO JOIN usuarios u ON u.CODUSUARIO=ug.CODUSUARIO WHERE u.USERID='jennifer.silva' ORDER BY ug.CODGRUPO")->fetchAll();
$legacyMenus=[];$q=$legacy->query('SELECT DISTINCT codgrupo,codmenu,dscmenu FROM vgruposxmenus WHERE dscmenu IS NOT NULL ORDER BY codgrupo,codmenu,dscmenu');foreach($q as $r)$legacyMenus[(int)$r['codgrupo']][(int)$r['codmenu']][]=$r['dscmenu'];
$user=$target->query("SELECT u.codusuario,u.userid,u.codperfil,p.codigo,p.nome FROM usuarios u LEFT JOIN perfis p ON p.codperfil=u.codperfil WHERE u.userid='jennifer.silva'")->fetch();
$targetMenus=$target->query('SELECT codmenu,codmenu_pai,codigo,label_pt,ativo FROM menus ORDER BY codmenu')->fetchAll();$byId=[];foreach($targetMenus as $m)$byId[(int)$m['codmenu']]=$m;
$paths=[];foreach($targetMenus as $m){$parts=[$m['label_pt']?:$m['codigo']];$parent=(int)($m['codmenu_pai']??0);$guard=0;while($parent&&isset($byId[$parent])&&$guard++<10){array_unshift($parts,$byId[$parent]['label_pt']?:$byId[$parent]['codigo']);$parent=(int)($byId[$parent]['codmenu_pai']??0);} $paths[(int)$m['codmenu']]=implode(' / ',$parts);}
$permissions=[];$q=$target->prepare('SELECT codmenu,pode_visualizar FROM vw_permissoes_grid WHERE codperfil=? AND pode_visualizar=1 ORDER BY codmenu');$q->execute([(int)$user['codperfil']]);foreach($q as $r)$permissions[(int)$r['codmenu']]=$paths[(int)$r['codmenu']]??(string)$r['codmenu'];
$groupTarget=[];$q=$target->query('SELECT codgrupo,codmenu FROM atlas_permissoes_legado WHERE status="MAPEADA" ORDER BY codgrupo,codmenu');foreach($q as $r)$groupTarget[(int)$r['codgrupo']][(int)$r['codmenu']]=$paths[(int)$r['codmenu']]??(string)$r['codmenu'];
$effectiveRows=[];$q=$target->prepare('SELECT pm.codmenu FROM perfil_menus pm WHERE pm.codperfil=? ORDER BY pm.codmenu');$q->execute([(int)$user['codperfil']]);foreach($q as $r)$effectiveRows[(int)$r['codmenu']]=$paths[(int)$r['codmenu']]??(string)$r['codmenu'];
$groupProfilesRows=[];$q=$target->query("SELECT p.codperfil,p.codigo,pm.codmenu FROM perfis p LEFT JOIN perfil_menus pm ON pm.codperfil=p.codperfil WHERE p.codigo IN ('ADM_DA_EMPRESA','FORNECEDOR','ATLAS_GRUPO_100001','ATLAS_GRUPO_100003') ORDER BY p.codperfil,pm.codmenu");foreach($q as $r)$groupProfilesRows[(string)$r['codigo']][]=$paths[(int)$r['codmenu']]??(string)$r['codmenu'];
echo json_encode(['legacy_groups'=>$legacyGroups,'legacy_menus'=>$legacyMenus,'target_user'=>$user,'target_visible_menus'=>$permissions,'target_effective_rows'=>$effectiveRows,'target_menus_by_legacy_group'=>$groupTarget,'target_group_profile_rows'=>$groupProfilesRows],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL;
